{"cards": [{"node_code": "N_07fce83f00990e3b", "definition": "研究双层结构客车及市郊通勤客车的车体构造、重心控制、制造工艺及运用技术，涵盖双层座车、双层卧车及短途高频次运行车辆。", "boundary": "本节点聚焦于具有双层车体结构或专为市郊短途通勤设计的客车。边界在于区分“双层/市郊”与“单层普速”（结构层数与运行场景）、“双层/市郊”与“高速”（速度等级与动力学要求）。若内容涉及双层车特有的重心稳定性、楼梯通道设计或市郊车的高频开关门机制，归入本节点；若仅为普通单层客车技术，归入硬软座车等节点。", "includes": ["双层客车车体结构、重心计算及制造工艺", "市郊客车（通勤车）的轻量化设计、高频运用及检修技术"], "excludes": ["单层普通座车、卧车的基础结构技术", "高速动车组（CRH等）的专用高速动力学技术"], "sibling_distinctions": [{"other_code": "N_85381c581a00718b", "rule": "区分依据为车体层数与运行场景：本节点侧重双层结构或市郊通勤特性；硬软座车侧重标准单层客车的座位布局与内饰。"}, {"other_code": "N_78640577081bc8c1", "rule": "区分依据为速度等级：本节点侧重中低速或市郊运行；高速客车侧重200km/h以上的高速动力学、空气阻力及轻量化技术。"}], "cross_boundary_rule": "若双层客车同时具备高速性能，若侧重双层结构稳定性归本节点，若侧重高速气动外形归高速客车。"}, {"node_code": "N_8f9883f1473c114c", "definition": "研究坐卧两用多功能客车及低重心设计客车的结构转换机构、重心优化技术及制造工艺，涵盖可变换座椅布局及低地板车辆。", "boundary": "本节点聚焦于具有“坐卧两用”功能转换机制或“低重心/低地板”结构特征的客车。边界在于区分“功能/重心特殊设计”与“标准固定布局”。若内容涉及座椅折叠机构、卧铺转换装置或降低车体重心以改善稳定性的结构设计，归入本节点；若仅为普通固定座位或标准重心客车，归入硬软座车或硬软卧车。", "includes": ["坐卧两用客车的座椅/卧铺转换机构设计及制造工艺", "低重心、低地板客车的车体结构优化及稳定性技术"], "excludes": ["固定式硬座或硬卧车的标准结构技术", "双层客车特有的上下层结构技术"], "sibling_distinctions": [{"other_code": "N_85381c581a00718b", "rule": "区分依据为功能灵活性：本节点侧重坐卧转换机构；硬软座车侧重固定座位布局。"}, {"other_code": "N_b09230e0135d65d4", "rule": "区分依据为功能灵活性：本节点侧重坐卧转换机构；硬软卧车侧重固定卧铺布局。"}], "cross_boundary_rule": "若坐卧两用车同时为双层结构，若侧重转换机构归本节点，若侧重双层车体结构归双层客车节点。"}, {"node_code": "N_78640577081bc8c1", "definition": "研究运行速度在200km/h及以上的高速铁路客车（含动车组拖车）的结构设计、空气动力学、轻量化材料及高速运用技术。", "boundary": "本节点聚焦于“高速”这一速度等级下的客车技术。边界在于区分“高速”与“普速/市郊”（速度等级、气动外形、材料要求）。若内容涉及高速运行下的气动噪声控制、车体轻量化、高速制动及抗疲劳设计，归入本节点；若仅为普通速度客车的结构，归入其他客车节点。注意：本节点指被牵引或动车组中的拖车部分，动力车归机车工程。", "includes": ["高速客车（动车组拖车）的车体结构、气动外形及轻量化设计", "高速运行下的动力学性能、噪声控制及高速检修技术"], "excludes": ["普速、市郊或双层客车的非高速专用技术", "机车（动力车）的牵引传动系统技术"], "sibling_distinctions": [{"other_code": "N_07fce83f00990e3b", "rule": "区分依据为速度等级：本节点侧重高速动力学与气动；双层/市郊客车侧重结构层数或短途通勤特性。"}, {"other_code": "N_85381c581a00718b", "rule": "区分依据为速度等级：本节点侧重高速专用技术；硬软座车侧重普速客车的通用结构。"}], "cross_boundary_rule": "若高速客车采用双层结构（罕见），若侧重高速气动归本节点，若侧重双层结构归双层客车节点。"}]}
